    organization: "ASTM International",
    specTitle: "Standard Practice for Surface Preparation and Marking of Metallic Surgical Implants",
    scope: "This practice covers the requirements for surface preparation, passivation, cleaning, and marking of metallic surgical implants. It applies to titanium and other implantable alloys to ensure biocompatibility and proper identification.",
    industries: ["Medical Devices", "Orthopedic Implants", "Surgical Instruments", "Dental"],
